CREATE OR REPLACE FUNCTION public.candidate_save(_id uuid,_record jsonb,_education jsonb DEFAULT '[]',_employment jsonb DEFAULT '[]',_assignments jsonb DEFAULT '{}') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.candidates; e public.candidate_education; w public.candidate_employment; item jsonb; ids uuid[]; typ text; creating boolean:=(_id IS NULL); BEGIN
 PERFORM public.candidate_assert(_id,CASE WHEN creating THEN 'candidates.create' ELSE 'candidates.edit' END);
 IF creating THEN c.id:=gen_random_uuid(); c.country:='India'; c.employment_status:='FRESHER'; c.has_career_gap:=false; c.currently_in_gap:=false; c.open_to_relocation:=false; c.roadmap_duration:=60; c.journey_status:='DRAFT'; c.portal_status:='NOT_ACTIVATED'; c.created_at:=now(); c.updated_at:=now(); c.created_by:=auth.uid(); ELSE SELECT * INTO c FROM public.candidates WHERE id=_id FOR UPDATE; END IF;
 c:=jsonb_populate_record(c,_record - ARRAY['id','candidate_code','created_at','updated_at','created_by','updated_by','portal_status','journey_status']);
 IF creating THEN c.journey_status:=coalesce(_record->>'journey_status','DRAFT'); IF c.journey_status NOT IN ('DRAFT','ENROLLED') THEN RAISE EXCEPTION 'New candidates must be Draft or Enrolled'; END IF; END IF;
 c.updated_by:=auth.uid();
 IF creating THEN INSERT INTO public.candidates SELECT (c).* RETURNING * INTO c; INSERT INTO public.candidate_status_history(candidate_id,new_status,changed_by) VALUES(c.id,c.journey_status,auth.uid()); ELSE UPDATE public.candidates SET (full_name,primary_mobile,personal_email,date_of_birth,gender,alternate_mobile,alternate_email,address_line_1,address_line_2,city,state,pin_code,country,profile_photo,employment_status,has_career_gap,gap_start_date,gap_end_date,currently_in_gap,gap_duration,gap_reason,gap_explanation,gap_internal_remarks,current_career_situation,existing_skills,tools_known,total_experience,relevant_it_experience,last_designation,last_industry,last_ctc,expected_ctc,preferred_locations,open_to_relocation,preferred_work_mode,candidate_preferred_role,enrollment_date,program_plan,program_status,roadmap_duration,tentative_start_date,tentative_end_date,source_reference,internal_remarks,updated_by) = (c.full_name,c.primary_mobile,c.personal_email,c.date_of_birth,c.gender,c.alternate_mobile,c.alternate_email,c.address_line_1,c.address_line_2,c.city,c.state,c.pin_code,c.country,c.profile_photo,c.employment_status,c.has_career_gap,c.gap_start_date,c.gap_end_date,c.currently_in_gap,c.gap_duration,c.gap_reason,c.gap_explanation,c.gap_internal_remarks,c.current_career_situation,c.existing_skills,c.tools_known,c.total_experience,c.relevant_it_experience,c.last_designation,c.last_industry,c.last_ctc,c.expected_ctc,c.preferred_locations,c.open_to_relocation,c.preferred_work_mode,c.candidate_preferred_role,c.enrollment_date,c.program_plan,c.program_status,c.roadmap_duration,c.tentative_start_date,c.tentative_end_date,c.source_reference,c.internal_remarks,auth.uid()) WHERE id=c.id; END IF;
 PERFORM public.candidate_log(c.id,CASE WHEN creating THEN 'Candidate Created' ELSE 'Candidate Updated' END);
 ids:=ARRAY[]::uuid[];
 FOR item IN SELECT value FROM jsonb_array_elements(_education) LOOP
 e:=NULL; IF item->>'id' IS NOT NULL THEN SELECT * INTO e FROM public.candidate_education WHERE id=(item->>'id')::uuid AND candidate_id=c.id; IF e.id IS NULL THEN RAISE EXCEPTION 'Invalid education record'; END IF; END IF;
 IF e.id IS NOT NULL AND (to_jsonb(e)-ARRAY['id','candidate_id','created_by','updated_by','created_at','updated_at']) @> (item-ARRAY['id','candidate_id','created_by','updated_by','created_at','updated_at']) THEN ids:=array_append(ids,e.id); CONTINUE; END IF;
 e:=jsonb_populate_record(e,item-ARRAY['candidate_id','created_by','updated_by','created_at','updated_at']); e.id:=coalesce(e.id,gen_random_uuid()); e.candidate_id:=c.id; e.created_by:=coalesce(e.created_by,auth.uid()); e.updated_by:=auth.uid(); e.created_at:=coalesce(e.created_at,now()); e.updated_at:=now();
 INSERT INTO public.candidate_education SELECT (e).* ON CONFLICT(id) DO UPDATE SET qualification_level=excluded.qualification_level,degree=excluded.degree,specialization=excluded.specialization,institution=excluded.institution,university=excluded.university,start_year=excluded.start_year,completion_year=excluded.completion_year,score=excluded.score,education_type=excluded.education_type,status=excluded.status,updated_by=auth.uid(),updated_at=now(); ids:=array_append(ids,e.id); PERFORM public.candidate_log(c.id,CASE WHEN item->>'id' IS NULL THEN 'Education Added' ELSE 'Education Updated' END); END LOOP;
 IF EXISTS(SELECT 1 FROM public.candidate_education WHERE candidate_id=c.id AND NOT(id=ANY(ids))) THEN PERFORM public.candidate_log(c.id,'Education Removed'); DELETE FROM public.candidate_education WHERE candidate_id=c.id AND NOT(id=ANY(ids)); END IF;
 ids:=ARRAY[]::uuid[];
 FOR item IN SELECT value FROM jsonb_array_elements(_employment) LOOP
 w:=NULL; IF item->>'id' IS NOT NULL THEN SELECT * INTO w FROM public.candidate_employment WHERE id=(item->>'id')::uuid AND candidate_id=c.id; IF w.id IS NULL THEN RAISE EXCEPTION 'Invalid employment record'; END IF; END IF;
 IF w.id IS NOT NULL AND (to_jsonb(w)-ARRAY['id','candidate_id','created_by','updated_by','created_at','updated_at']) @> (item-ARRAY['id','candidate_id','created_by','updated_by','created_at','updated_at']) THEN ids:=array_append(ids,w.id); CONTINUE; END IF;
 w:=jsonb_populate_record(w,item-ARRAY['candidate_id','created_by','updated_by','created_at','updated_at']); w.id:=coalesce(w.id,gen_random_uuid()); w.candidate_id:=c.id; w.currently_working:=coalesce(w.currently_working,false); IF w.currently_working THEN w.end_date:=NULL; END IF; w.created_by:=coalesce(w.created_by,auth.uid()); w.updated_by:=auth.uid(); w.created_at:=coalesce(w.created_at,now()); w.updated_at:=now();
 INSERT INTO public.candidate_employment SELECT (w).* ON CONFLICT(id) DO UPDATE SET company_name=excluded.company_name,designation=excluded.designation,employment_type=excluded.employment_type,industry=excluded.industry,location=excluded.location,start_date=excluded.start_date,end_date=excluded.end_date,currently_working=excluded.currently_working,ctc=excluded.ctc,role_description=excluded.role_description,technologies=excluded.technologies,reason_for_leaving=excluded.reason_for_leaving,remarks=excluded.remarks,updated_by=auth.uid(),updated_at=now(); ids:=array_append(ids,w.id); PERFORM public.candidate_log(c.id,CASE WHEN item->>'id' IS NULL THEN 'Employment Added' ELSE 'Employment Updated' END); END LOOP;
 IF EXISTS(SELECT 1 FROM public.candidate_employment WHERE candidate_id=c.id AND NOT(id=ANY(ids))) THEN PERFORM public.candidate_log(c.id,'Employment Removed'); DELETE FROM public.candidate_employment WHERE candidate_id=c.id AND NOT(id=ANY(ids)); END IF;
 FOR typ IN SELECT jsonb_object_keys(_assignments) LOOP IF nullif(_assignments->>typ,'') IS NOT NULL THEN PERFORM public.candidate_set_assignment(c.id,typ,(_assignments->>typ)::uuid); END IF; END LOOP;
 RETURN c.id; END $$;
REVOKE ALL ON FUNCTION public.candidate_save(uuid,jsonb,jsonb,jsonb,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.candidate_save(uuid,jsonb,jsonb,jsonb,jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.candidate_options() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN public.has_permission(auth.uid(),'candidates.view') THEN jsonb_build_object('plans',(SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY p.sort_order),'[]') FROM public.candidate_program_plans p WHERE is_active),'staff',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',p.id,'full_name',p.full_name,'role_key',r.key)),'[]') FROM public.profiles p JOIN public.user_roles ur ON ur.user_id=p.id JOIN public.roles r ON r.id=ur.role_id WHERE p.status='ACTIVE' AND r.is_active AND r.is_staff AND r.key IN ('career_consultant','technical_reviewer','placement_executive')),'portal_users',CASE WHEN public.has_permission(auth.uid(),'candidates.portal') THEN (SELECT coalesce(jsonb_agg(jsonb_build_object('id',p.id,'full_name',p.full_name,'email',p.email)),'[]') FROM public.profiles p JOIN public.user_roles ur ON ur.user_id=p.id JOIN public.roles r ON r.id=ur.role_id WHERE p.status='ACTIVE' AND r.key='candidate' AND r.is_active AND NOT EXISTS(SELECT 1 FROM public.candidate_portal_links l WHERE l.user_id=p.id)) ELSE '[]'::jsonb END) ELSE NULL END $$;
REVOKE ALL ON FUNCTION public.candidate_options() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.candidate_options() TO authenticated;
CREATE OR REPLACE FUNCTION public.candidate_set_portal(_id uuid,_user uuid DEFAULT NULL,_disable boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE existing uuid; BEGIN
 PERFORM public.candidate_assert(_id,'candidates.portal'); PERFORM 1 FROM public.candidates WHERE id=_id FOR UPDATE; SELECT user_id INTO existing FROM public.candidate_portal_links WHERE candidate_id=_id;
 IF _disable THEN IF existing IS NULL THEN RAISE EXCEPTION 'No portal is linked'; END IF; UPDATE public.candidate_portal_links SET disabled_at=now(),updated_by=auth.uid(),updated_at=now() WHERE candidate_id=_id; UPDATE public.candidates SET portal_status='DISABLED',updated_by=auth.uid() WHERE id=_id; PERFORM public.candidate_log(_id,'Portal Disabled'); RETURN; END IF;
 _user:=coalesce(existing,_user); IF _user IS NULL THEN RAISE EXCEPTION 'Choose a Candidate-role user'; END IF;
 IF existing IS NOT NULL AND _user<>existing THEN RAISE EXCEPTION 'A portal account is already linked'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.profiles p JOIN public.user_roles ur ON ur.user_id=p.id JOIN public.roles r ON r.id=ur.role_id WHERE p.id=_user AND p.status='ACTIVE' AND r.key='candidate' AND r.is_active) THEN RAISE EXCEPTION 'Choose an active Candidate-role user'; END IF;
 INSERT INTO public.candidate_portal_links(candidate_id,user_id,created_by,updated_by) VALUES(_id,_user,auth.uid(),auth.uid()) ON CONFLICT(candidate_id) DO UPDATE SET disabled_at=NULL,activated_at=now(),updated_by=auth.uid(),updated_at=now(); UPDATE public.candidates SET portal_status='ACTIVE',updated_by=auth.uid() WHERE id=_id; PERFORM public.candidate_log(_id,'Portal Activated'); END $$;
REVOKE ALL ON FUNCTION public.candidate_set_portal(uuid,uuid,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.candidate_set_portal(uuid,uuid,boolean) TO authenticated;